def numberOfCombinations(num):
    MOD = 10 ** 9 + 7
    n = len(num)
    if num[0] == '0':
        return 0
    lcp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if num[i] == num[j]:
                lcp[i][j] = lcp[i + 1][j + 1] + 1

    def leq(x, y, L):
        c = lcp[x][y]
        if c >= L:
            return True
        return num[x + c] <= num[y + c]

    f = [[0] * (n + 1) for _ in range(n + 1)]
    pre = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(0, i):
            L = i - j
            if num[j] == '0':
                f[i][j] = 0
            elif j == 0:
                f[i][j] = 1
            else:
                jpmin = j - L
                lo = max(0, jpmin + 1)
                hi = j - 1
                s = 0
                if hi >= lo:
                    s = (pre[j][hi] - (pre[j][lo - 1] if lo > 0 else 0)) % MOD
                if jpmin >= 0 and leq(jpmin, j, L):
                    s = (s + f[j][jpmin]) % MOD
                f[i][j] = s % MOD
        run = 0
        for j in range(0, i):
            run = (run + f[i][j]) % MOD
            pre[i][j] = run
        for j in range(i, n + 1):
            pre[i][j] = run
    return sum(f[n][j] for j in range(n)) % MOD
